def evaluate_expression(expression):
    # Replace bitwise operators with equivalent operations
    replacements = {
        '^': lambda a, b: a & b,
        '|': lambda a, b: a | b,
        '&': lambda a, b: a & b
    }
    stack = []
    for token in expression:
        if token in replacements:
            expr = stack.pop() & stack.pop()
            stack[-1] = replacements[token](expr, stack.pop())
        else:
            stack.append(int(token))
    return stack[0]

