from functools import lru_cache

def longest_common_prefix(s1, s2):
    i = 0
    while i < len(s1) and i < len(s2) and s1[i] == s2[i]:
        i += 1
    return i

@lru_cache(None)
def lcp_sum(s):
    n = len(s)
    total = 0
    for i in range(1, n):
        total += len(s) - i
        total += len(s) - 1 - i
        prefix_len = longest_common_prefix(s[:i], s[i:])
        if prefix_len > 0:
            total -= len(s) - i - prefix_len
            total += len(s) - 1 - i - prefix_len
    return total

def solve_queries(n, queries, initial_strings):
    queries_result = []
    for query in queries:
        if query[0] == 1:
            l, r = query[1], query[2]
            interval = []
            for i in range(l-1, r):
                interval.append(initial_strings[i-1])
            current_string = ''.join(interval)
            initial_strings[l-1:r] = current_string.split()
        elif query[0] == 2:
            position, new_string = query[1], query[2]
            initial_strings[position-1] = new_string
        else:
            l, r = query[1], query[2]
            interval = []
            for i in range(l-1, r):
                interval.append(initial_strings[i-1])
            current_string = ''.join(interval)
            queries_result.append(lcp_sum(current_string))
    return queries_result

