def evaluate_expression(expression):
    operands = []
    operators = []
    for char in expression:
        if char.isdigit():
            operands.append(int(char))
        elif char in '&|^':
            operators.append(char)

    result = operands[0]
    i = 0
    j = 1
    while i < len(operators) and j < len(operands):
        if operators[i] == '&':
            result &= operands[j]
        elif operators[i] == '|':
            result |= operands[j]
        elif operators[i] == '^':
            result ^= operands[j]
        i += 1
        j += 1

    return result

