import sys

def min_mod(n, k, a):
    # SORT A
    a.sort()
    # PRECOMPUTE MOD DIFERS BY 1
    dif = [a[1] - a[0]]
    for i in range(1, n - 1):
        dif.append(a[i + 1] - a[i])
    for j in range(n - 1):
        for i in range(j + 1, n - 1):
            dif.append(a[i + 1] - a[j])
    # LOOK THAT THERE ARE NO INF SQLLS
    # SKILL INTO DEGUE USE BFS
    km = {}
    dist = [0] + [float('inf')] * (n - 1)
    dist[0] = 0
    que = [0]
    while que:
        v = que.pop(0)
        for i in range(1, n - i):
            res = a[v + i] - a[v + i - 1]
            if res in km:
                if res in km[res]:
                    return dist[0]
                # THIS CHECK WE NEED THE SECOND ITERATIVE OF SIMULATION
                if km[res][dist[v]] < dist[v + i - 1]:
                    km[res] = {dist[v]: dist[v + i - 1]}
                elif km[res][dist[v]] == dist[v + i - 1] and km[res][dist[v]] + 1 >= dist[v + i - 1]:
                    km[res][dist[v]] += 1
                else:
                    km[res][dist[v]] = dist[v + i - 1]
            else:
                km.setdefault(res, {dist[v]: dist[v + i - 1]})
            if dist[i + n - 1 - v] > dist[v + i + 1 - v] + dif[i]:
                dist[i + n - 1 - v] = dist[v + i + 1 - v] + dif[i]
                que.append(i + n - 1 - v)
                if not dist[i + n - 1 - v] in km[res]:
                    km[res][dist[i + n - 1 - v]] = dist[i + n - 1 - v]
    return max(dist)

