MOD = 1000000007

def power(a, b):
    if b == 0:
        return 1
    elif b == 1:
        return a
    elif b % 2 == 0:
        half_power = power(a, b // 2)
        return (half_power * half_power) % MOD
    elif b % 2 == 1:
        return (a * power(a, b - 1)) % MOD

def countMarbles(N):
    memo = [[0, 0] for _ in range(N + 1)]
    memo[0] = [1, 0]

    for i in range(1, N + 1):
        if N in memo[i-1]:
            memo[i][0] = (memo[i][0] + 1 + memo[i][1]) % MOD
        if i + 1 in memo[i-1]:
            memo[i][1] = (memo[i-1][0] + 1 + memo[i-1][1]) % MOD
        memo[i][0] = (memo[i-1][0] + i) % MOD
        memo[i][1] = (memo[i-1][1] + i) % MOD
        memo[i][2] = (memo[i][0] * memo[i][1] + memo[i][0] * memo[i-1][0]) % MOD
        memo[i][3] = (memo[i][2] * 2 + memo[i-1][2]) % MOD

    return memo[N][2] + memo[N][3]

