from collections import defaultdict
def find_pairs(n, max_wind):
    dp = [0] * 60001  # dp[i] represents the number of ways to find a pair up to distance i
    pairs = 0

    # Create a binary indexed tree-like data structure
    def range_add(i, val):
        k = len(dp) // 3 + 1
        while i < len(dp) and i < dp[-1]:
            i += k
            dp[i] += val

    def range_sum(i):
        k = len(dp) // 3 + 1
        res = 0
        while i > 0:
            res += dp[i]
            i -= k
            k //= 3
        return res

    for x, v in planes:
        if v > 0:
            range_add(abs(x), 1)  # Count intersections for positive x values
        else:
            range_add(-abs(x), 1)  # Count intersections for negative x values

    pairs = 0
    # Calculate the number of ways to find a pair
    for x in range(-100000, 100001):
        for v in range(-100000, 100001):
            if v > 0:
                pairs += range_sum(abs(v) - abs(x))  # Check for overlapping intervals
            else:
                pairs += range_sum(-abs(v) - abs(x))  # Add the complement pairs

    return pairs

