from math import log2

class LongestCommonPrefix:
    def longestCommonPrefix(self, str_list):
        if not str_list:
            return 0

        n = len(str_list)
        max_length = 1

        for i in range(1, n):
            if i == 1:
                common_prefix_1_i = str_list[i]
                for j in range(1, len(str_list[i])):
                    if common_prefix_1_i[0:len(common_prefix_1_i) - j] != str_list[j]:
                        common_prefix_1_i = str_list[i][0:len(common_prefix_1_i) - j]
                        break
                    elif j == len(str_list[i]) - 1:
                        max_length = len(common_prefix_1_i)

            else:
                common_prefix_i_1 = str_list[i][i-1]
                for j in range(1, len(str_list[i])):
                    if str_list[0][0:len(common_prefix_i_1) - j] != str_list[j]:
                        common_prefix_i_1 = str_list[i][0:len(common_prefix_i_1) - j]
                        break
                    elif j == len(str_list[i]) - 1:
                        max_length = max_len = max(max_length, len(common_prefix_i_1))

                for j in range(i + 1, n):
                    common_prefix = str_list[j][0:len(common_prefix_i_1)]
                    j = i + 1
                    while j < n and str_list[j][0:len(common_prefix_i_1)] == common_prefix:
                        if str_list[j][0:len(common_prefix_i_1) + 1] == str_list[j][1:len(common_prefix_i_1)] and common_prefix_i_1 == str_list[j][0]:
                            max_length = max_len = max(
                                max_length, int(log2(j - i)) + len(common_prefix_i_1) + 1)
                            break
                        j += 1
        return max_length

