import sys

def bfs(r1, c1, r2, c2):
    """Determine if a path exists from (r1, c1) to (r2, c2) without barriers."""
    from collections import defaultdict
    from collections import deque

    graph = defaultdict(list)
    queue = deque([(r1, c1)])

    while queue:
        r, c = queue.popleft()
        if r == r2 and c == c2:
            return True
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr <= m - 1 and 0 <= nc <= m - 1 and (nr, nc) not in graph[(r, c)] and (nr, nc) not in [l[::-1] for l in connected]:
                graph[(r, c)].append((nr, nc))
                queue.append( (nr, nc) )
    return False

def solve():
    n, m, q = map(int, input().split())
    connected = set()
    for _ in range(q):
        t, r1, c1, r2, c2 = map(int, input().split())
        if t == 1:
            if not connected:
                graph[(r1, c1)] = [(r2, c2)]
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r1 + dr, c1 + dc
                    if 0 <= nr <= m - 1 and 0 <= nc <= m - 1:
                        graph[(nr, nc)].append((r2, c2))
                        connected.add((nr, nc, r2, c2))
            else:
                graph[(r1, c1)], graph[(r2, c2)] = None, None
                for l in graph:
                    graph[l].clear()
        elif t == 2:
            if not connected:
                graph.clear()
                connected = set()
            graph[(r1, c1)] = [(r2, c2)]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r1 + dr, c1 + dc
                if 0 <= nr <= m - 1 and 0 <= nc <= m - 1:
                    graph[(nr, nc)].append((r2, c2))
                    connected.add((nr, nc, r2, c2))
        else:
            for x, y in graph[(r1, c1)]:
                connected.discard((x, y, r1, c1))
            connected.discard((r1, c1, r2, c2))
    for x, y in graph[(r1, c1)]:
        connected.discard((x, y, r1, c1))
    return "Yes" if connected else "No"

def main():
    print(solve())

