from collections import defaultdict

def min_repeating_segments(band, segments):
    occurrence = defaultdict(lambda: float('inf'))
    for start, end in segments:
        overlap, res = 0, float('inf')
        while start + overlap <= end:
            valid_overlap = min(len(band[start+overlap:end]), len(band[start:start+overlap+1]))
            res = min(res, max(valid_overlap // 2, occurrence[start+overlap:end]))
            overlap += 1
            for i in range(start, start+overlap+1):
                occurrence[i] += valid_overlap
        new_occurrence = defaultdict(lambda: float('inf'))
        for i in range(start+1, start+overlap):
            new_occurrence[i+1] = new_occurrence[i] + len(band[i+1])
        for i in occurrence:
            occurrence[i] = new_occurrence.get(i, float('inf')) + len(band[i+1])
    return occurrence[len(band)]

# Pseudocode
def bands(n, s):
    occurrence = defaultdict(lambda: float('inf'))
    for i in range(n):
        if i >= len(s):
            break
        band = s[i:]
        count = len(band)
        while i + count + 1 <= n:
            j = i + count + 1
            i, min_banded = j, j
            next_start = None
            next_end = n
            while i < j:
                if i == next_start and j == next_end:
                    min_banded = min(band[i], min_banded)
                    break
                elif band[i] == min_banded:
                    next_start = i
                    min_banded = band[i]
                elif band[j] == min_banded:
                    next_end = j
                    min_banded = band[j]
                i, j = next_start + 1, j - 1    
            if min_banded == len(band):
                for i in range(min_banded+1):
                    occurrence[i] += count
                    count //= 2  
    return (occurrence[len(band)], min(min_banded // 2 + 1 if len(band) != count//2 else 1, occurrence[len(band)]))

