from typing import List

def parse_input() -> tuple:
    n, m, q = map(int, input().split())
    actions: List[List[int]] = []
    for _ in range(q):
        t, r1, c1, r2, c2 = map(int, input().split())
        actions.append([t, r1, c1, r2, c2])
    return n, m, q, actions

def over_barrier(r1: int, c1: int, r2: int, c2: int) -> bool:
    return not (0 <= r1 <= r2 and 0 <= c1 <= c2 and r1 < r2 and c1 < c2)

def check_feasible(action: List[int]) -> str:
    t, r1, c1, r2, c2 = action
    if t == 1:  # place barrier
        return "No"
        # check if any exit from r1 to r2 exists
        for r in range(r1, r2 + 1):
            if over_barrier(r, c1, r, c2):
                return "No"
    elif t == 2:  # remove barrier
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if over_barrier(r, c1, r, c2):
                    return "No"
    elif t == 3:  # walk from r1 to r2
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if over_barrier(r, c1, r, c2):
                    return "No"
        return "Yes"
    else:
        assert False

    return "Yes"

n, m, q, actions = parse_input()
for action in actions:
    print(check_feasible(action))
