def calculate_bomb_cost(p, q):
    def merge_and_count(bombs):
        counts = {0: 0, 1: 0}
        for bomb in bombs:
            if bomb == 0:
                counts[bomb] -= 1
            elif bomb == 1:
                counts[bomb] += 1
        return counts

    costs = []
    for target in q:
        if target == 0:
            bombs = []
        else:
            bombs = list(0, 2) + [i for i in q[:-1] if i < target]
        sorted_bombs = merge_and_count(bombs)
        for bomb, count in sorted_bombs.items():
            costs.append(min(count, 1))

    return costs

